mapper.select:
select role_code from safety_sys_user_role
where del_flag = '0'
and user_id = #{userId}

select * from safety_employee_message


        and emp_no = #{empNo}


        and phone_no = #{empNo}


limit 1

select car_no,car_color,car_model,employee_no as empNo,vehicle_type,lock_flag from safety_employee_private_car
where delete_flag= '0'

    and employee_no = #{empNo}


    and phone_no = #{empNo}

select t.oper_time ,t.io_flag,t1.AN_FACTORY_NAME as factoryName,t1.DEVICE_NAME from safety_build_in_out_history t
inner join safety_build_device t1 on t.device_code = t1.device_code
where t.emp_no= #{empNo}
